Expression:
from a in db->Contracts_calc where AND(
                                 a->MainDocument_calc==true,
                                 LESSEQ(ENDOFDAY(a->ValidUntil_calc), $_creationDate),
                                 OR(a->RenewalConditions_calc->Status->Code=="draft", a->RenewalConditions_calc->Status->Code=="inapproval", a->RenewalConditions_calc->Status->Code=="signing", a->RenewalConditions_calc->Status->Code=="new"),
                                 OR(a->Status->Code=="active", a->Status->Code=="out")                                 
                                ) select a->id
